mapper.select:
SELECT
    TOTLE_TRADE_ID
FROM
    TRD_FIN_PRODUCT_DEAL_TOTAL

    TRADE_STATUS = #{TRADE_STATUS_01}
    AND (IS_CANCEL IS NULL OR IS_CANCEL = 'N')

        AND TRADE_DATE = #{dealDate,jdbcType=DATE}


        AND BUSI_TYPE = #{busiType,jdbcType=DATE}



            #{ps,jdbcType=VARCHAR}




            #{portfolioId,jdbcType=VARCHAR}

SELECT
    DISTINCT A.TOTLE_TRADE_ID
FROM
    TRD_PRODUCT_DEAL A
INNER JOIN SETTLE_TRANS_TG_MAPPING B
	ON A.TRADE_ID = B.TRADE_ID_TG
INNER JOIN TRD_FIN_PRODUCT_DEAL_TOTAL C
	ON A.TOTLE_TRADE_ID = C.TOTLE_TRADE_ID

    A.TRADE_STATUS = #{TRADE_STATUS_01}
    AND (A.IS_CANCEL IS NULL OR A.IS_CANCEL = 'N')

        AND TO_CHAR(B.CREATE_TIME, 'yyyy-MM-dd') = #{dealDateStr,jdbcType=VARCHAR}


        AND C.BUSI_TYPE = #{busiType,jdbcType=DATE}



            #{busiType,jdbcType=VARCHAR}




            #{ps,jdbcType=VARCHAR}




            #{portfolioId,jdbcType=VARCHAR}

SELECT
    tpd.TRADE_ID
FROM TRD_PRODUCT_DEAL tpd
INNER JOIN TRD_PRODUCT_DEAL_ADD tpda ON tpd.TRADE_ID = tpda.TRADE_ID

    tpd.TRADE_STATUS = #{TRADE_STATUS_01}
    AND (tpd.IS_CANCEL IS NULL OR tpd.IS_CANCEL = 'N')

        AND tpd.TRADE_DATE = #{dealDate,jdbcType=DATE}



            #{type,jdbcType=VARCHAR}




            #{ps,jdbcType=VARCHAR}




            #{portfolioId,jdbcType=VARCHAR}


    AND tpd.TOTLE_TRADE_ID is null

SELECT
    DISTINCT tpd.TRADE_ID
FROM TRD_PRODUCT_DEAL tpd
INNER JOIN TRD_PRODUCT_DEAL_ADD tpda ON tpd.TRADE_ID = tpda.TRADE_ID
INNER JOIN SETTLE_TRANS_TG_MAPPING sttm ON tpd.TRADE_ID = sttm.TRADE_ID_TG

    tpd.TRADE_STATUS = #{TRADE_STATUS_01}
    AND (tpd.IS_CANCEL IS NULL OR tpd.IS_CANCEL = 'N')

        AND TO_CHAR(sttm.CREATE_TIME, 'yyyy-MM-dd') = #{dealDateStr,jdbcType=VARCHAR}



            #{type,jdbcType=VARCHAR}




            #{ps,jdbcType=VARCHAR}




            #{portfolioId,jdbcType=VARCHAR}


    AND tpd.TOTLE_TRADE_ID is null

